class Solution {
  public int wordsTyping(String[] sentence, int rows, int cols) {
    String s = String.join(" ", sentence) + " ";
    int len = s.length(), pos = 0; // pos: characters of the repeated sentence placed so far
    for (int r = 0; r < rows; r++) {
      pos += cols;
      if (s.charAt(pos % len) == ' ') pos++; // the row ends exactly at a word boundary
      else while (pos > 0 && s.charAt((pos - 1) % len) != ' ') pos--; // back off the cut word
    }
    return pos / len;
  }
}
